namespace nexthire_api.WorkflowAutomation.Documents;

public interface INexaDocumentsClient
{
    /// <summary>
    /// Calls Nexa.Documents <c>POST .../documents/{documentId}/download-url</c>
    /// to obtain a read-only SAS URL (generated by that service).
    /// </summary>
    Task<NexaDocumentDownloadUrl> CreateDownloadUrlAsync(
        Guid organizationId,
        string documentId,
        CancellationToken cancellationToken = default);
}

public sealed class NexaDocumentDownloadUrl
{
    public required string Url { get; init; }
    public DateTimeOffset ExpiresAt { get; init; }
}
